WHERE p.name = "John Alexander Thain" OR "John Alexander Thain" IN p.aliases 
RETURN c.name AS CompanyName;

MATCH (c:Company {name: "Best Buy"})-[:hasBoardMember]->(m:Person) 
RETURN m.name AS board_member, m.date_of_birth AS dob, m.date_of_death AS dod
ORDER BY m.name;

MATCH (c:Company)-[:basedIn]->(co:Country), (c)-[:hasCEO]->(p:Person)
WHERE co.name = "Czech Republic"
RETURN DISTINCT p.name AS CEO, c.name AS Company;
